#define PACKET_OUT_DEFINITION_COUNT_LC245_2 \
    ((int)(sizeof(g_packet_out_definitions_lc245_2) / sizeof(g_packet_out_definitions_lc245_2[0])))

/** Canonical PKTOUT_NAME_* -> wire opcode; -1 = absent from this rev. */
static inline int
packetout_code_lc245_2(int pkt_out_name)
{
    for( int i = 0; i < PACKET_OUT_DEFINITION_COUNT_LC245_2; i++ )
    {
        if( g_packet_out_definitions_lc245_2[i].name == pkt_out_name )
        {
            return g_packet_out_definitions_lc245_2[i].code;
        }
    }
    return -1;
}

